function isWorkspaceExportNameForFormat(format, name) {
  const extensions = {
    a3m: [".a3m"],
    "aligned-fasta": [".afa", ".aln", ".aln-fasta", ".fa", ".fas", ".fasta"],
    bed: [".bed"],
    clustal: [".aln", ".clustal", ".clw"],
    csv: [".csv"],
    embl: [".embl"],
    fasta: [".fa", ".faa", ".fas", ".fasta", ".fna"],
    fastq: [".fastq", ".fq"],
    genbank: [".gb", ".gbk", ".genbank"],
    gff3: [".gff", ".gff3"],
    gtf: [".gtf"],
    json: [".json"],
    newick: [".newick", ".nwk", ".tree"],
    pdf: [".pdf"],
    stockholm: [".sto", ".stk", ".stockholm"],
    svg: [".svg"],
    tsv: [".tsv"],
    vcf: [".vcf"]
  };
  const lowerName = name.toLowerCase();
  return extensions[format].some(
    (extension) => lowerName.length > extension.length && lowerName.endsWith(extension)
  );
}
